import * as React from "react"
import { Link } from "gatsby"
import Header from "../components/Header"
import Seo from "../components/Seo"
import * as s from "../components/admin/Admin.module.css"
import TemplateBoard from "../components/admin/TemplateBoard"
import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "../lib/supabase"
import { useAuth } from "../context/auth"

/**
 * The admin workbench — MTC-FCS-035.
 * ============================================================================
 * One screen for the one job it was asked for: find somebody who paid and
 * cannot get in, and put the right email address on their account.
 *
 * ── THE TOKEN IS TYPED, NEVER BUILT IN ─────────────────────────────────────
 * `ADMIN_TOKEN` lives in the server environment with no GATSBY_ prefix, so it
 * is not in this bundle. It is typed here and kept in sessionStorage, which
 * dies with the tab. Nate's "we will spend more time securing it later" is
 * the plan; until then the gate is one shared secret and this page is honest
 * about that.
 *
 * ── IT SHOWS WHICH SOURCES ANSWERED ────────────────────────────────────────
 * Stripe, the accounts table and Supabase auth can each be unconfigured or
 * unreachable. "No account" and "could not look" must not look the same while
 * somebody is on the phone with a customer.
 */

const STORE_KEY = "fcs.admin-token"

/* Declared out here, not inside the page component: a component created
   during render is a new type every render, so React unmounts and remounts
   the subtree — and an input loses focus after one keystroke. */

const Field = ({ id, label, value, onChange, placeholder, mono }) => (
  <div className={s.field}>
    <label htmlFor={id}>{label}</label>
    <input
      id={id}
      className={mono ? s.mono : undefined}
      value={value}
      placeholder={placeholder}
      onChange={e => onChange(e.target.value)}
      autoComplete="off"
      spellCheck="false"
    />
  </div>
)

const Pill = ({ tone = "", children }) => (
  <span
    className={`${s.pill} ${tone === "good" ? s.pillGood : tone === "warn" ? s.pillWarn : ""}`}
  >
    {children}
  </span>
)

const money = (amount, currency) =>
  amount == null
    ? "—"
    : new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: (currency || "usd").toUpperCase(),
      }).format(amount / 100)

const when = value => (value ? new Date(value).toLocaleString() : "—")

const AdminPage = () => {
  const [token, setToken] = React.useState("")
  const [query, setQuery] = React.useState({ recoveryCode: "", email: "", customerId: "" })
  const [result, setResult] = React.useState(null)
  const [requests, setRequests] = React.useState(null)
  const [newEmail, setNewEmail] = React.useState("")
  const [busy, setBusy] = React.useState("")
  const [error, setError] = React.useState("")
  const [done, setDone] = React.useState("")

  // Kept for the tab's lifetime only.
  React.useEffect(() => {
    try {
      setToken(sessionStorage.getItem(STORE_KEY) || "")
    } catch {
      /* Private mode, or storage blocked. Typing it again is the fallback. */
    }
  }, [])

  const remember = value => {
    setToken(value)
    try {
      sessionStorage.setItem(STORE_KEY, value)
    } catch {
      /* not fatal */
    }
  }

  const call = async (path, init = {}) => {
    const res = await fetch(path, {
      ...init,
      headers: {
        "Content-Type": "application/json",
        "x-admin-token": token,
        ...(init.headers || {}),
      },
    })
    const body = await res.json().catch(() => ({}))
    if (!res.ok) throw new Error(body.message || `HTTP ${res.status}`)
    return body
  }

  const lookup = async e => {
    e.preventDefault()
    setError("")
    setDone("")
    setBusy("lookup")
    try {
      const body = await call("/api/admin/lookup", {
        method: "POST",
        body: JSON.stringify(query),
      })
      setResult(body)
      setNewEmail(body.account?.email || "")
    } catch (err) {
      setError(err.message)
      setResult(null)
    } finally {
      setBusy("")
    }
  }

  const loadQueue = async () => {
    setError("")
    setBusy("queue")
    try {
      const body = await call("/api/admin/support")
      setRequests(body.requests || [])
      if (body.message) setError(body.message)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy("")
    }
  }

  const fixEmail = async () => {
    const userId = result?.account?.id || result?.authUsers?.[0]?.id
    if (!userId) {
      setError("No auth user id — look somebody up first.")
      return
    }
    setError("")
    setDone("")
    setBusy("fix")
    try {
      const body = await call("/api/admin/fix-email", {
        method: "POST",
        body: JSON.stringify({ userId, email: newEmail, sendLink: true }),
      })
      setDone(
        body.link
          ? `${body.message} Email could not be sent — pass this link on by hand: ${body.link}`
          : body.message
      )
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy("")
    }
  }

  const account = result?.account
  const usable = token.trim().length >= 16



  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className="container">
          <div className={s.head}>
            <h1 className={s.title}>Admin</h1>
            <Pill tone={usable ? "good" : "warn"}>{usable ? "token set" : "token needed"}</Pill>
          </div>
          <p className={s.lead}>
            For the case where somebody paid, mistyped their email address, and cannot log in.
            Find them by the recovery code from their receipt, then put the right address on the
            account and send them a way back in.
          </p>

          {/* ── THE TEMPLATE LIBRARY — FCS-073 ───────────────────────────
              Gated on an admin ACCOUNT, not the token below: that token is a
              shared secret with nobody's name on it, which is the wrong
              credential for deciding what every customer can choose from.

              The board asks the server and renders what it is told. It used
              to ask here as well, and the two answers were a race nobody
              needed — one question, one place. */}
          <div className={s.card}>
            <TemplateBoard />
          </div>

          {/* Its own page — FCS-073(b). Deciding what a plan gets is a
              different errand from rescuing one locked-out customer, and
              the two should not be scrolled past each other. */}
          <p className={s.lead}>
            <Link to="/admin/users/">See every user and their account →</Link>
            {" · "}
            <Link to="/admin/limits/">Set usage limits by plan →</Link>
            {" · "}
            <Link to="/admin/settings/">Settings →</Link>
            {" · "}
            <Link to="/admin/logs/">Activity log →</Link>
            {" · "}
            <Link to="/admin/go-live/">Go-live checklist →</Link>
            {" · "}
            <Link to="/admin/pipeline/">Launch console →</Link>
          </p>

          <div className={s.card}>
            <h2 className={s.cardTitle}>Admin token</h2>
            <div className={s.row}>
              <Field
                id="ad-token"
                label="ADMIN_TOKEN"
                value={token}
                onChange={remember}
                placeholder="the value from the server environment"
                mono
              />
            </div>
            <p className={s.note}>
              Kept in this tab only. It is a shared secret, not an account — treat it like the
              Stripe key, and change it when somebody leaves.
            </p>
          </div>

          <form className={s.card} onSubmit={lookup}>
            <h2 className={s.cardTitle}>Find somebody</h2>
            <div className={s.row}>
              <Field
                id="ad-code"
                label="Recovery code"
                value={query.recoveryCode}
                onChange={v => setQuery(q => ({ ...q, recoveryCode: v }))}
                placeholder="FCS-7K2M-93QX"
                mono
              />
              <Field
                id="ad-email"
                label="Email address"
                value={query.email}
                onChange={v => setQuery(q => ({ ...q, email: v }))}
                placeholder="what they think they typed"
              />
              <Field
                id="ad-customer"
                label="Stripe customer"
                value={query.customerId}
                onChange={v => setQuery(q => ({ ...q, customerId: v }))}
                placeholder="cus_…"
                mono
              />
              <button type="submit" className={s.button} disabled={!usable || busy === "lookup"}>
                {busy === "lookup" ? "Looking…" : "Look up"}
              </button>
            </div>
            <p className={s.note}>
              The recovery code is the one that works when nobody knows which email address was
              used — it is stored on the Stripe subscription, not on an account.
            </p>
            {error ? <p className={s.error}>{error}</p> : null}
            {done ? <p className={s.ok}>{done}</p> : null}
          </form>

          {result ? (
            <div className={s.card}>
              <h2 className={s.cardTitle}>What came back</h2>

              <div className={s.sources}>
                {Object.entries(result.sources || {}).map(([name, state]) => (
                  <Pill key={name} tone={/error|not configured/.test(state) ? "warn" : ""}>
                    {name}: {state}
                  </Pill>
                ))}
              </div>

              <div className={s.scroll} style={{ marginTop: 16 }}>
                <table className={s.table}>
                  <tbody>
                    <tr>
                      <th>Account</th>
                      <td className={s.mono}>{account?.id || "— none found —"}</td>
                    </tr>
                    {account ? (
                      <>
                        <tr>
                          <th>Email on record</th>
                          <td>{account.email || "—"}</td>
                        </tr>
                        <tr>
                          <th>Tier / status</th>
                          <td>
                            {account.tierName} ({account.tier}) · {account.status}
                          </td>
                        </tr>
                        <tr>
                          <th>Confirmed</th>
                          <td>{when(account.emailConfirmedAt)}</td>
                        </tr>
                        <tr>
                          <th>Site</th>
                          <td className={s.mono}>{account.siteId || "—"}</td>
                        </tr>
                        <tr>
                          <th>Recovery code</th>
                          <td className={s.mono}>{account.recoveryCode || "—"}</td>
                        </tr>
                        <tr>
                          <th>Stripe</th>
                          <td className={s.mono}>
                            {account.stripeCustomerId || "—"} · {account.subscriptionStatus || "—"}
                          </td>
                        </tr>
                      </>
                    ) : null}
                  </tbody>
                </table>
              </div>

              {result.payments?.length ? (
                <div className={s.scroll} style={{ marginTop: 18 }}>
                  <table className={s.table}>
                    <thead>
                      <tr>
                        <th>Subscription</th>
                        <th>Status</th>
                        <th>Amount</th>
                        <th>Started</th>
                        <th>On the payment</th>
                        <th>Code</th>
                      </tr>
                    </thead>
                    <tbody>
                      {result.payments.map(p => (
                        <tr key={p.id}>
                          <td className={s.mono}>{p.id}</td>
                          <td>{p.status}</td>
                          <td>
                            {money(p.amount, p.currency)}
                            {p.interval ? `/${p.interval}` : ""}
                          </td>
                          <td>{when(p.created)}</td>
                          <td>
                            {p.customerEmail || "—"}
                            {p.subdomain ? ` · ${p.subdomain}` : ""}
                          </td>
                          <td className={s.mono}>{p.recoveryCode || "—"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className={s.note}>No payment found for that search.</p>
              )}

              {result.authUsers?.length ? (
                <p className={s.note}>
                  Supabase auth:{" "}
                  {result.authUsers
                    .map(u => `${u.email} (${u.confirmed ? "confirmed" : "NOT confirmed"})`)
                    .join(", ")}
                </p>
              ) : null}

              <div className={s.row} style={{ marginTop: 18 }}>
                <Field
                  id="ad-new-email"
                  label="Correct the email address to"
                  value={newEmail}
                  onChange={setNewEmail}
                  placeholder="the address that actually works"
                />
                <button
                  type="button"
                  className={s.button}
                  onClick={fixEmail}
                  disabled={!usable || busy === "fix" || !/.+@.+\..+/.test(newEmail)}
                >
                  {busy === "fix" ? "Changing…" : "Change it and send a link"}
                </button>
              </div>
              <p className={s.note}>
                This confirms the new address as well as setting it — they are here because a
                confirmation email never arrived, so leaving it unconfirmed changes nothing for
                them. The sign-in link is sent by us, not by Supabase&rsquo;s rate-limited mailer.
              </p>
            </div>
          ) : null}

          <div className={s.card}>
            <div className={s.head}>
              <h2 className={s.cardTitle}>People waiting</h2>
              <button
                type="button"
                className={`${s.button} ${s.ghost}`}
                onClick={loadQueue}
                disabled={!usable || busy === "queue"}
              >
                {busy === "queue" ? "Loading…" : "Load requests"}
              </button>
            </div>

            {requests === null ? (
              <p className={s.note}>Nothing loaded yet.</p>
            ) : requests.length === 0 ? (
              <p className={s.note}>Nobody is waiting.</p>
            ) : (
              <div className={s.scroll}>
                <table className={s.table}>
                  <thead>
                    <tr>
                      <th>When</th>
                      <th>Who</th>
                      <th>Reach them</th>
                      <th>Code</th>
                      <th>Message</th>
                    </tr>
                  </thead>
                  <tbody>
                    {requests.map(r => (
                      <tr key={r.id}>
                        <td>{when(r.receivedAt)}</td>
                        <td>
                          {r.name || "—"}
                          {r.business ? ` · ${r.business}` : ""}
                        </td>
                        <td>
                          {r.phone || "—"}
                          {r.email ? ` · ${r.email}` : ""}
                        </td>
                        <td className={s.mono}>{r.recoveryCode || "—"}</td>
                        <td>{r.message || "—"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </main>
    </>
  )
}

export const Head = () => <Seo title="Admin" description="Internal tools." noindex />

export default AdminPage
