import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import * as s from "./TemplateBoard.module.css"

/**
 * The template library, curated — FCS-073.
 * ============================================================================
 * Three columns, one per tier, and a design is moved between them by dragging
 * it. The board IS the model: where a card sits is which tier may choose it,
 * so there is no separate dropdown to disagree with the layout.
 *
 * ── PUBLISHING IS SEPARATE FROM CATEGORISING ───────────────────────────────
 * Dragging decides WHO may have it; the toggle decides WHETHER anybody can
 * yet. They are different decisions and the screen keeps them apart — a
 * design can sit in Premium for a week while it is finished, and nobody sees
 * it until somebody says so.
 *
 * ── EVERY MOVE SAVES IMMEDIATELY, AND SAYS SO ──────────────────────────────
 * No Save button: a board with unsaved state is a board somebody closes
 * having lost twenty minutes of arranging. The card goes where it was
 * dropped, the write happens, and if it fails the card goes back and the
 * reason is on screen — rather than a UI that quietly disagrees with the
 * database.
 *
 * ── DRAG AND DROP IS NOT THE ONLY WAY ──────────────────────────────────────
 * Each card also carries plain buttons for the other two tiers. Dragging is
 * a mouse gesture: it is awkward on a phone, impossible from a keyboard, and
 * invisible to a screen reader.
 */

const COLUMNS = [
  { id: "free", label: "Free", note: "anybody can choose these" },
  { id: "premium", label: "Premium", note: "paid hosting" },
  { id: "leads", label: "Lead Generation", note: "top tier" },
]

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("admin-templates"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  const payload = await res.json().catch(() => ({}))
  return { ok: res.ok, status: res.status, body: payload }
}

const TemplateBoard = () => {
  const [templates, setTemplates] = React.useState(null)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState("")
  const [denied, setDenied] = React.useState(false)
  const [dragging, setDragging] = React.useState("")
  const [over, setOver] = React.useState("")

  const load = React.useCallback(async () => {
    setBusy("loading")
    setError("")
    const res = await call({ action: "list" })
    setBusy("")
    if (!res.ok) {
      /* 403 is not a fault — it is the answer. Somebody who is not an
         administrator is told that plainly rather than being shown a red
         error about a request they were never meant to make. */
      setDenied(res.status === 403 || res.status === 401)
      setError(
        res.status === 403 || res.status === 401
          ? ""
          : res.body.message || `Could not load the library (HTTP ${res.status}).`
      )
      return
    }
    setDenied(false)
    setTemplates(res.body.templates || [])
  }, [])

  React.useEffect(() => {
    load()
  }, [load])

  const sync = async () => {
    setBusy("sync")
    setError("")
    const res = await call({ action: "sync" })
    setBusy("")
    if (!res.ok) {
      setError(res.body.message || "The library could not be read.")
      return
    }
    await load()
  }

  /* Optimistic, then reconciled. The card moves the instant it is dropped
     because that is what the hand expects; if the write fails the previous
     state is put back and the reason is shown. */
  const change = async (id, patch) => {
    const before = templates
    setTemplates(list => list.map(row => (row.id === id ? { ...row, ...patch } : row)))
    setError("")

    const res = await call({ action: "set", id, ...patch })
    if (!res.ok) {
      setTemplates(before)
      setError(res.body.message || "That change did not save.")
    }
  }

  const onDrop = (event, category) => {
    event.preventDefault()
    setOver("")
    const id = dragging || event.dataTransfer.getData("text/plain")
    setDragging("")
    if (!id) return
    const row = (templates || []).find(t => t.id === id)
    if (!row || row.category === category) return
    change(id, { category })
  }

  if (denied) {
    return (
      <div className={s.wrap}>
        <h2 className={s.title}>Template library</h2>
        <p className={s.note}>
          This account is not an administrator, so the template library is not shown here.
        </p>
      </div>
    )
  }

  if (error && !templates) {
    return (
      <div className={s.wrap}>
        <p className={s.error}>{error}</p>
        <button type="button" className={s.ghost} onClick={load}>
          Try again
        </button>
      </div>
    )
  }

  if (!templates) return <p className={s.note}>Loading the library…</p>

  const published = templates.filter(t => t.published).length

  return (
    <div className={s.wrap}>
      <div className={s.head}>
        <div>
          <h2 className={s.title}>Template library</h2>
          <p className={s.note}>
            {templates.length} design{templates.length === 1 ? "" : "s"}, {published} published.
            Drag one between the columns to change who can choose it.
          </p>
        </div>
        <button type="button" className={s.ghost} onClick={sync} disabled={busy === "sync"}>
          {busy === "sync" ? "Pulling…" : "Pull from library"}
        </button>
      </div>

      {error ? <p className={s.error}>{error}</p> : null}

      <div className={s.board}>
        {COLUMNS.map(column => {
          const rows = templates
            .filter(row => row.category === column.id)
            .sort((a, b) => a.position - b.position || a.name.localeCompare(b.name))

          return (
            <section
              key={column.id}
              className={s.column}
              data-over={over === column.id ? "true" : undefined}
              onDragOver={event => {
                event.preventDefault()
                setOver(column.id)
              }}
              onDragLeave={() => setOver(o => (o === column.id ? "" : o))}
              onDrop={event => onDrop(event, column.id)}
            >
              <header className={s.columnHead}>
                <h3 className={s.columnTitle}>{column.label}</h3>
                <span className={s.columnCount}>{rows.length}</span>
              </header>
              <p className={s.columnNote}>{column.note}</p>

              <ul className={s.cards}>
                {rows.length === 0 ? (
                  <li className={s.empty}>Nothing here yet</li>
                ) : (
                  rows.map(row => (
                    <li
                      key={row.id}
                      className={s.card}
                      draggable
                      data-dragging={dragging === row.id ? "true" : undefined}
                      onDragStart={event => {
                        setDragging(row.id)
                        event.dataTransfer.setData("text/plain", row.id)
                        event.dataTransfer.effectAllowed = "move"
                      }}
                      onDragEnd={() => setDragging("")}
                    >
                      <div className={s.cardHead}>
                        <span className={s.cardName}>{row.name}</span>
                        <span className={s.cardId}>{row.id}</span>
                      </div>
                      {row.description ? (
                        <p className={s.cardDesc}>{row.description}</p>
                      ) : null}

                      <div className={s.cardFoot}>
                        <button
                          type="button"
                          className={s.toggle}
                          data-on={row.published ? "true" : undefined}
                          onClick={() => change(row.id, { published: !row.published })}
                        >
                          {row.published ? "Published" : "Not published"}
                        </button>

                        {/* Dragging is a mouse gesture. These are the same
                            move, available to everybody else. */}
                        <span className={s.moves}>
                          {COLUMNS.filter(c => c.id !== row.category).map(c => (
                            <button
                              key={c.id}
                              type="button"
                              className={s.move}
                              title={`Move to ${c.label}`}
                              onClick={() => change(row.id, { category: c.id })}
                            >
                              {c.label}
                            </button>
                          ))}
                        </span>
                      </div>
                    </li>
                  ))
                )}
              </ul>
            </section>
          )
        })}
      </div>
    </div>
  )
}

export default TemplateBoard
